#!/usr/bin/env node
/**
 * Bundles the Lambda handler into packages/server/lambda-bundle for Pulumi upload.
 * Requires: yarn build:sdk (for types) and esbuild.
 */
import { cpSync, mkdirSync, rmSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

import * as esbuild from "esbuild"

const __dirname = dirname(fileURLToPath(import.meta.url))
const serverRoot = join(__dirname, "..")
const outDir = join(serverRoot, "lambda-bundle")

rmSync(outDir, { recursive: true, force: true })
mkdirSync(outDir, { recursive: true })

await esbuild.build({
  entryPoints: [join(serverRoot, "src", "lambda.ts")],
  bundle: true,
  platform: "node",
  target: "node20",
  format: "cjs",
  outfile: join(outDir, "lambda.js"),
  sourcemap: true,
  /**
   * CJS has no import.meta; rewrite to a __filename-based URL so resolvePublicDir
   * (and any other import.meta.url uses) keep working without empty-import-meta warnings.
   */
  banner: {
    js: "var __import_meta_url=require(\"url\").pathToFileURL(__filename).href;",
  },
  define: {
    "import.meta.url": "__import_meta_url",
  },
  external: [
    "koffi",
    "@aws-sdk/*",
  ],
  logLevel: "info",
})

cpSync(join(serverRoot, "public"), join(outDir, "public"), { recursive: true })

writeFileSync(
  join(outDir, "package.json"),
  JSON.stringify(
    {
      name: "limetry-server-lambda",
      private: true,
      main: "lambda.js",
    },
    null,
    2,
  ),
)

writeFileSync(
  join(outDir, "README.md"),
  [
    "# Lambda bundle",
    "",
    "Generated by `yarn workspace @limetry/server build:lambda`.",
    "Handler: `lambda.handler`",
    "",
    "Native FFI (`koffi` / limetry-ffi) is external — ship a Lambda layer or",
    "container image when MPC/FFI routes are required. Policy/audit HTTP paths",
    "that stay in pure TypeScript work without it once product pivot completes.",
    "",
  ].join("\n"),
)

console.log(`Wrote ${outDir}/lambda.js (handler: lambda.handler)`)
